import java.util.Arrays;

public class Solution {
    // O(n²): para cada início, estende até repetir.
    static int forcaBruta(String s) {
        int melhor = 0;
        for (int i = 0; i < s.length(); i++) {
            boolean[] visto = new boolean[128];
            for (int j = i; j < s.length(); j++) {
                if (visto[s.charAt(j)]) break;
                visto[s.charAt(j)] = true;
                melhor = Math.max(melhor, j - i + 1);
            }
        }
        return melhor;
    }

    // O(n): ultimo[c] diz onde c apareceu; a janela pula direto para depois dele.
    static int janela(String s) {
        int[] ultimo = new int[128];
        Arrays.fill(ultimo, -1);
        int melhor = 0, l = 0;
        for (int r = 0; r < s.length(); r++) {
            char c = s.charAt(r);
            if (ultimo[c] >= l) l = ultimo[c] + 1;
            ultimo[c] = r;
            melhor = Math.max(melhor, r - l + 1);
        }
        return melhor;
    }
}

