import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.Random;

class SolutionTest {
    @Test void exemplos() {
        for (var caso : new Object[][]{{"abcabcbb", 3}, {"bbbbb", 1}, {"pwwkew", 3}, {"", 0}, {"abba", 2}}) {
            assertEquals(caso[1], Solution.forcaBruta((String) caso[0]), "forcaBruta " + caso[0]);
            assertEquals(caso[1], Solution.janela((String) caso[0]), "janela " + caso[0]);
        }
    }

    @Test void asDuasConcordam() {
        var rnd = new Random(1);
        for (int t = 0; t < 300; t++) {
            var sb = new StringBuilder();
            for (int i = rnd.nextInt(30); i > 0; i--) sb.append((char) ('a' + rnd.nextInt(5)));
            assertEquals(Solution.forcaBruta(sb.toString()), Solution.janela(sb.toString()), sb.toString());
        }
    }

    @Test void janelaGrande() {
        var sb = new StringBuilder();
        for (int i = 0; i < 200_000; i++) sb.append((char) (33 + i % 90));
        assertEquals(90, Solution.janela(sb.toString()));
    }
}
